package net.minecraft.client.gui.components;import net.minecraft.network.chat.Component;import net.minecraft.client.gui.components.events.GuiEventListener;import net.minecraft.client.gui.narration.NarratableEntry;public class Button implements GuiEventListener,Renderable,NarratableEntry{public boolean active=true,visible=true;public OnPress press;public net.minecraft.network.chat.Component label;public void press(){if(active&&visible)press.onPress(this);}public interface OnPress{void onPress(Button b);}public static Builder builder(Component c,OnPress p){return new Builder(c,p);}public static class Builder{Component c;OnPress p;public Builder(Component c,OnPress p){this.c=c;this.p=p;}public Builder bounds(int x,int y,int w,int h){return this;}public Button build(){Button b=new Button();b.label=c;b.press=p;return b;}}}
